import { MakeLogicType, afterMount, connect, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { propertyDefinitionsUsageMetricsCreate } from '~/generated/core/api'
import type { PropertyUsageEntryApi, PropertyUsageMetricsItemApi } from '~/generated/core/api.schemas'

export interface PropertyUsageLogicProps {
    entry: PropertyUsageEntryApi
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface propertyUsageLogicValues {
    currentProjectId: number | string // teamLogic
    queryUsage: PropertyUsageMetricsItemApi | null
    queryUsageFailed: boolean
    queryUsageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface propertyUsageLogicActions {
    loadQueryUsage: () => any
    loadQueryUsageFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadQueryUsageSuccess: (
        queryUsage: PropertyUsageMetricsItemApi | null,
        payload?: any
    ) => {
        queryUsage: PropertyUsageMetricsItemApi | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface propertyUsageLogicMeta {
    key: string
}

export type propertyUsageLogicType = MakeLogicType<
    propertyUsageLogicValues,
    propertyUsageLogicActions,
    PropertyUsageLogicProps,
    propertyUsageLogicMeta
>

export const propertyUsageLogic = kea<propertyUsageLogicType>([
    path((key) => ['scenes', 'data-management', 'definition', 'usage', 'propertyUsageLogic', key]),
    props({} as PropertyUsageLogicProps),
    key(({ entry }) => `${entry.type}/${entry.group_type_index ?? ''}/${entry.name}`),
    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),
    loaders(({ values, props }) => ({
        queryUsage: [
            null as PropertyUsageMetricsItemApi | null,
            {
                loadQueryUsage: async (): Promise<PropertyUsageMetricsItemApi | null> => {
                    const { results } = await propertyDefinitionsUsageMetricsCreate(String(values.currentProjectId), {
                        properties: [props.entry],
                    })
                    return results[0] ?? null
                },
            },
        ],
    })),
    reducers({
        queryUsageFailed: [
            false,
            {
                loadQueryUsage: () => false,
                loadQueryUsageSuccess: () => false,
                loadQueryUsageFailure: () => true,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadQueryUsage()
    }),
])
